/**
 * Entering VR from a page drawn with WebGPU.
 *
 * WebXR presents only on WebGL2 (xrSupport.ts), and a page keeps the engine
 * it started with. So on WebGPU the first press of Enter VR loads the page
 * again with one fixed word in its address, `?vr=again`, which starts the
 * engine in WebGL2 for that load only. The browser does not carry the press
 * across a load, and a VR session can only start from a press, so the page
 * comes back with the button armed and a line asking for one more. The
 * word is taken off the address once read: loading the page again by hand
 * is WebGPU again.
 *
 * The word can do nothing but choose the older engine, and it is never
 * read from inside a world's own address. Loaded only on that press, or on
 * the load it asked for: a visitor who never presses it pays nothing.
 */

const PARAM = 'vr';
const AGAIN = 'again';
/** The line beside the button. */
export const VR_NOTE_ID = 'webverse-xr-note';
export const VR_WORDS = { getting: 'Getting ready for VR…', ready: 'Ready. Press Enter VR again.' } as const;
const BUTTON_ID = 'webverse-xr-enter';
const ARMED = 'data-webverse-xr-armed';

/** `href` with the word that loads it in WebGL2 for VR, its place (the fragment) kept. */
export function vrAgainAddress(href: string): string {
  const url = new URL(href);
  url.searchParams.set(PARAM, AGAIN);
  return url.href;
}

/** `href` without that word. */
export function withoutVrAgain(href: string): string {
  const url = new URL(href);
  url.searchParams.delete(PARAM);
  return url.href;
}

/** Puts `text` in the line beside the button, making it if need be. On the client's own page it sits under the button. */
function say(doc: Document, text: string): HTMLElement {
  let note = doc.getElementById(VR_NOTE_ID);
  if (note === null) {
    note = doc.createElement('p');
    note.id = VR_NOTE_ID;
    note.setAttribute('role', 'status');
    note.style.cssText =
      'position:fixed;right:12px;top:52px;z-index:11;margin:0;padding:6px 12px;border-radius:6px;' +
      'font:13px/1.3 system-ui,sans-serif;color:#dfe3ea;background:#1b1b22;pointer-events:none';
    doc.body.appendChild(note);
  }
  note.textContent = text;
  return note;
}

/**
 * The first press on WebGPU: say what is happening, and load the page
 * again in WebGL2. A load that is refused, or that the browser never
 * makes, leaves no line saying it is getting ready: the line goes at once,
 * or after `giveUpMs`.
 */
export function reloadForVr(win: { document: Document; location: { href: string; replace(to: string): void } }, giveUpMs = 10_000): void {
  const note = say(win.document, VR_WORDS.getting);
  const done = (): void => {
    if (note.textContent === VR_WORDS.getting) note.remove();
  };
  try {
    win.location.replace(vrAgainAddress(win.location.href));
  } catch {
    done();
    return;
  }
  setTimeout(done, giveUpMs);
}

/** The load asked for: the word comes off the address, and the button is armed. */
export function armed(win: Window): void {
  win.history.replaceState(win.history.state, '', withoutVrAgain(win.location.href));
  showArmed(win.document);
}

/** Back in WebGL2: the button stands out, with a line asking for the press; that press puts the line away. */
export function showArmed(doc: Document): void {
  const button = doc.getElementById(BUTTON_ID);
  if (button === null) return;
  button.setAttribute(ARMED, '');
  button.style.outline = '3px solid #c7d2fe';
  say(doc, VR_WORDS.ready);
  button.addEventListener(
    'click',
    () => {
      button.removeAttribute(ARMED);
      button.style.outline = '';
      doc.getElementById(VR_NOTE_ID)?.remove();
    },
    { once: true },
  );
}
